text:
{
  "hypotheses": [
    {
      "id": "h1",
      "kind": "feature_code",
      "rationale": "Уже есть fe_total_dd как сумма отопительных и охлаждающих градусо-дней, но структура климатической нагрузки несёт дополнительную информацию: при одинаковой сумме HDD+CDD здания в холодном и жарком климате могут потреблять энергию по-разному. Отношение HDD к CDD явно разделяет режимы преобладания отопления/охлаждения.",
      "patch": {
        "features.custom": [
          "+fe_hdd_cdd_ratio"
        ]
      },
      "feature_spec": "fe_hdd_cdd_ratio = heating_degree_days_c / (cooling_degree_days_c + 1)",
      "expected": "Небольшое снижение RMSE за счёт более явного разделения климатических режимов, особенно в случаях, где общая градусо-дневная нагрузка похожа, но баланс отопления и охлаждения различен.",
      "cost": "low"
    },
    {
      "id": "h2",
      "kind": "model",
      "rationale": "Таргет имеет сильный правый хвост, а log1p ухудшил метрику, значит модель лучше работает в исходной шкале. Однако RMSE чувствителен к аномально высоким значениям EUI. Huber-потеря может смягчить влияние выбросов без сжатия шкалы, которое уже показало себя вредным.",
      "patch": {
        "model.params.objective": "huber",
        "model.params.huber_delta": 100
      },
      "feature_spec": null,
      "expected": "Уменьшение вклада выбросов в RMSE; возможно небольшое ухудшение на типичных значениях, но в целом снижение RMSE за счёт более устойчивой оптимизации.",
      "cost": "medium"
    },
    {
      "id": "h3",
      "kind": "config",
      "rationale": "facility_type содержит 60 категорий, и редкие уровни могут давать шум в native-кодировании. Объединение редких категорий может стабилизировать обучение и уменьшить переобучение на малочисленных типах зданий.",
      "patch": {
        "preprocess.rare_min_count": 50
      },
      "feature_spec": null,
      "expected": "Небольшое снижение RMSE за счёт более стабильного представления редких facility_type; если редкие категории не несли полезного сигнала, дельта будет близка к нулю.",
      "cost": "low"
    },
    {
      "id": "h4",
      "kind": "model",
      "rationale": "XGBoost ещё не пробовался и может иначе обрабатывать пропуски, взаимодействия и масштабирование признаков. CatBoost уже показал ухудшение, но XGBoost — другое семейство, и разнообразие моделей полезно для поиска альтернативного прогноза.",
      "patch": {
        "model.name": "xgboost",
        "model.params": {
          "learning_rate": 0.05,
          "max_depth": 7,
          "subsample": 0.8,
          "colsample_bytree": 0.8,
          "min_child_weight": 5,
          "reg_lambda": 1
        }
      },
      "feature_spec": null,
      "expected": "Возможен небольшой прирост RMSE, если XGBoost лучше уловит взаимодействия на текущих признаках; иначе изменение будет отклонено.",
      "cost": "medium"
    }
  ]
}
